count-lines.script:
export const meta = {
  name: 'count-lines',
  description: 'Count lines of every .txt file in parallel, then sum them',
  phases: [{ title: 'Count', detail: 'one agent per file' }, { title: 'Sum', detail: 'add the counts' }],
}
const NUM = { type: 'object', properties: { n: { type: 'number' } }, required: ['n'] }
const FILES = ['a.txt', 'b.txt', 'c.txt', 'd.txt']
phase('Count')
const counts = await parallel(FILES.map(f => () =>
  agent(`Count the lines in ./${f} with wc -l. Return just the number.`, { label: `count ${f}`, phase: 'Count', model: 'haiku', schema: NUM })))
phase('Sum')
const total = await agent(`Add ${counts.map(c => c && c.n).join(', ')}. Return just the sum.`, { label: 'sum', phase: 'Sum', model: 'haiku', schema: NUM })
return { total: total && total.n }
